{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer korrekt, at udtalelsen er vejledende og ikke bindende. Men det bagatelliserer, at Udbetaling Danmark er den afgørende myndighed: det hævder, at UDK 'normalt ikke' træffer afgørelser om SU-handicaptillæg, og at det er 'den relevante SU-myndighed'. Det strider mod SU-bekendtgørelsen § 36, stk. 1, og vejledningen, hvor Udbetaling Danmark træffer afgørelsen. Svaret udelader også AES's to vurderingspunkter (påvirkning af arbejdsevnen og om et studiejob ikke kan varetages) i den form, kilderne bruger. Det tilføjer en 'sagligt begrundet'-regel og en 'formel AES-afgørelse', som kilderne ikke nævner."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element, hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, er dækket nogenlunde via 'konkrete følger … for muligheden for erhvervsarbejde'. Det andet kritiske element, om funktionsevnen er så nedsat, at et studiejob ikke kan varetages, er ikke gengivet. Svaret nævner 'meget begrænsede muligheder for erhvervsarbejde' som SU-målestok, men ikke studiejob-vurderingen. Det understøttende element om, at udtalelsen bygger på sagens dokumenter uden undersøgelse, mangler også."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om den er bindende. Det afviser dog delvist spørgsmålets forudsætning om Udbetaling Danmark."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lovbestemmelse, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så kildestøtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttede retsregler og påstande: at Udbetaling Danmark 'normalt ikke' træffer afgørelser om SU-handicaptillæg, og at en anden 'SU-myndighed' gør det. Det tilføjer også, at myndigheden ikke bør se bort fra udtalelsen uden saglig begrundelse, at en AES-vurdering af erhvervsevnetab ikke nødvendigvis besvarer SU-spørgsmålet, og at en 'formel AES-afgørelse' kan have virkning i arbejdsskadesagen. Intet af dette findes i materialet. Den myndighedspåstand modsiger materialet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den krævede kvalifikation er bevaret: udtalelsen er vejledende og ikke bindende for den afgørende myndighed. Det er ikke fuldt ud knyttet til Udbetaling Danmark, men hovedforbeholdet fremgår."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret siger, at udtalelsen ikke er bindende for den myndighed, der afgør sagen, men afviser samtidig, at Udbetaling Danmark er den myndighed. Det svarer dermed ikke sammenhængende på spørgsmålet om Udbetaling Danmark. Den alternative 'anden ydelse'-gren er spekulativ."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Normalt ikke' om Udbetaling Danmarks afgørelseskompetence og 'bør ikke se bort' er modaliteter, som kilderne ikke støtter. Kilden siger entydigt, at Udbetaling Danmark kan indhente udtalelsen, og at den ikke er bindende. Ordet 'som udgangspunkt' om ikke-bindende er svagere end kildens kategoriske formulering."
    }
  },
  "xhaile_coverage": {
    "A68": {
      "label": "partial",
      "reason": "Svaret dækker, at udtalelsen er vejledende, og delvist påvirkningen af arbejdsevnen. Det mangler studiejob-vurderingen, at udtalelsen bygger på den foreliggende dokumentation uden undersøgelse, at Udbetaling Danmark kan anmode om den, og at Udbetaling Danmark betaler udgifterne. Det benægter desuden Udbetaling Danmarks rolle."
    }
  },
  "overall_notes": "Svaret rammer den centrale pointe om, at udtalelsen er vejledende og ikke bindende, men afviser fejlagtigt Udbetaling Danmarks rolle, udelader studiejob-kriteriet og dokumentgrundlaget, tilføjer uunderstøttede regler og citerer ingen kilder."
}

